# ---- protection clause threshold: the parent control's weakest
# DISCOVERY year win rate (stage 1) ----
T_PROT = 0.5454545454545454


def _pip_of(sym):
    return 0.01 if "JPY" in sym else 0.0001


def _pos32(h, l, c, idx):
    """Close position in the last-32-M15-bar range
    [0, 1]: (entry close - lowest low of bars
    idx-31..idx) / (highest high - lowest low of
    the same bars); None when unavailable."""
    if idx < 31:
        return None
    hh = float(np.max(h[idx - 31:idx + 1]))
    ll = float(np.min(l[idx - 31:idx + 1]))
    if hh <= ll:
        return None
    return (float(c[idx]) - ll) / (hh - ll)


def _trade_outcome(bars, sym, entry_s, side, dist_pips):
    """(exit_epoch, net25) for one candidate at a
    FIXED pip distance; exit/net are None while the
    trade is unresolved in the available bars and
    the 48h cap bar is not yet present. Locked
    replay form (SL-first in one bar)."""
    ts, _o, h, l, c = bars
    idx = int(np.searchsorted(ts, entry_s - 900))
    if idx >= len(ts) or ts[idx] != entry_s - 900:
        return None, None
    ph = h[idx + 1:idx + 1 + MAXHOLD_BARS]
    pl = l[idx + 1:idx + 1 + MAXHOLD_BARS]
    fwd = ts[idx + 1:idx + 1 + MAXHOLD_BARS]
    entry = float(c[idx])
    pip = _pip_of(sym)
    dist_price = dist_pips * pip
    tp_price = TP_FRAC * dist_price  # NEW LAW: TP = 2 x SL
    if side > 0:
        sl_hit = pl <= entry - dist_price
        tp_hit = ph >= entry + tp_price
    else:
        sl_hit = ph >= entry + dist_price
        tp_hit = pl <= entry - tp_price
    isl = int(np.argmax(sl_hit)) if sl_hit.any()\
        else 10 ** 9
    itp = int(np.argmax(tp_hit)) if tp_hit.any()\
        else 10 ** 9
    if isl == 10 ** 9 and itp == 10 ** 9:
        if len(ph) >= MAXHOLD_BARS:
            gross = side * (float(c[idx + MAXHOLD_BARS])
                            - entry) / pip
            return entry_s + MAX_HOLD * 3600,\
                gross - COST_PIPS
        return None, None
    if isl <= itp:
        return int(fwd[isl]) + 900, -dist_pips - COST_PIPS
    return int(fwd[itp]) + 900, TP_FRAC * dist_pips - COST_PIPS


def _slot_rows(T, m15_bars, equations):
    """Candidate rows for one slot: for every symbol
    with an available entry bar, both sides, each
    carrying its own equation's score / expectancy /
    in-band flag / fixed distance. Canonical order:
    symbol index, side desc (BUY first)."""
    rows = []
    hour = (T % 86400) // 3600
    for sym in SYMBOLS:
        bars = m15_bars.get(sym)
        if bars is None:
            continue
        ts, _o, h, l, c = bars
        idx = int(np.searchsorted(ts, T - 900))
        if idx >= len(ts) or ts[idx] != T - 900\
                or idx < 31:
            continue
        pos = _pos32(h, l, c, idx)
        if pos is None:
            continue
        eq = equations[sym]
        lo, hi = BANDS[eq["band"]]
        entry_px = float(c[idx])
        for side in (1, -1):
            adj = pos if side > 0 else 1.0 - pos
            bucket = 0 if adj < BUCKET_E1 else\
                (1 if adj < BUCKET_E2 else 2)
            score = float(eq["cells"].get(
                (hour, side, bucket), eq["prior"]))
            xp, net = _trade_outcome(bars, sym, T, side,
                                     eq["dist"])
            rows.append({
                "sym": sym, "side": side,
                "dist": eq["dist"],
                "score": score,
                "exp": (2.0 * score - 1.0) * eq["dist"]
                       - COST_PIPS,
                "in_band": bool(lo < adj < hi),
                "entry_px": entry_px,
                "pos_adj": float(adj),
                "exit": xp, "net": net,
                "entry_s": int(T)})
    return rows


def _margin(row, equations):
    """Expectancy margin: E - E(tau_s) for the row's
    own symbol (variant R2Y-B's fallback key)."""
    eq = equations[row["sym"]]
    return row["exp"] - ((2.0 * eq["tau"] - 1.0)
                         * eq["dist"] - COST_PIPS)


def _weeknum(ts):
    import datetime as _dt
    from datetime import timezone as _tz
    return _dt.datetime.fromtimestamp(
        int(ts), tz=_tz.utc).isocalendar()[1]


def _year_of(ts):
    import datetime as _dt
    from datetime import timezone as _tz
    return _dt.datetime.fromtimestamp(
        int(ts), tz=_tz.utc).year


_EMPTY = frozenset()


def _cell_of(row, slot):
    return (int(row[0]), int((int(slot) % 86400) // 3600),
            int(row[1]), int(row[9]))


def _cands(rows, max_exit, ts, taus):
    by_sym = {}
    for r in rows:
        if max_exit.get(r[0], -1) > ts:
            continue
        by_sym.setdefault(r[0], []).append(r)
    if not by_sym:
        return None

    def best(idxs, kf):
        return min(idxs, key=lambda r: (
            -kf(r), r[0], 0 if r[1] > 0 else 1))

    band_best, any_best = {}, {}
    for sym, rs in by_sym.items():
        br = [r for r in rs if r[6]]
        if br:
            band_best[sym] = best(br, lambda r: r[4])
        any_best[sym] = best(rs, lambda r: r[5])
    firing = {s: r for s, r in band_best.items()
              if r[3] >= taus[s]}
    if firing:
        return 1, list(firing.values()), "exp"
    if band_best:
        return 2, list(band_best.values()), "margin"
    return 3, list(any_best.values()), "margin"


def _rank(row, rank_key):
    return row[4] if rank_key == "exp" else row[5]


def _sel_plain(rows, max_exit, ts, taus):
    c = _cands(rows, max_exit, ts, taus)
    if c is None:
        return None, 0
    tier, cand, rank_key = c
    return min(cand, key=lambda r: (
        -_rank(r, rank_key), r[0],
        0 if r[1] > 0 else 1)), tier


def _sel_wdiv(rows, max_exit, ts, taus, lw, losing):
    c = _cands(rows, max_exit, ts, taus)
    if c is None:
        return None, 0
    tier, cand, rank_key = c

    def ov(r):
        return len(lw.get(_cell_of(r, ts), _EMPTY) & losing)

    return min(cand, key=lambda r: (
        ov(r), -_rank(r, rank_key), r[0],
        0 if r[1] > 0 else 1)), tier


class FillState:
    """The composed fill: the parent's expectancy fill
    law with the WDIV hook (R4-014 form) under the
    worst-year PROTECTION clause (R4-023 form) at
    T_PROT. Slots are processed in chronological order;
    a kept pick blocks its symbol until its
    candle-replayed exit; state (blocking ledger, WDIV
    running week-net, per-year running picks/wins)
    follows the COMMITTED pick; the week-net and
    year state reset per era segment."""

    def __init__(self, equations=None,
                 lose_weeks=None):
        self._equations = equations if equations is not None else EQUATIONS_GAPD
        self._lose_weeks = lose_weeks if lose_weeks is not None else LOSE_WEEKS_GAPD
        self.max_exit = {}
        self.picks = []
        self.run_net = {}
        self.year_state = {}
        self._era = None
        self.ev = {e: {"slots_total": 0, "picks": 0,
                       "unfilled_no_rows": 0,
                       "unfilled_all_blocked": 0,
                       "tier2": 0, "tier3": 0}
                   for e in ("disc", "audit")}

    def to_dict(self):
        return {
            "max_exit": {k: ("inf" if v == float("inf")
                             else v)
                         for k, v in self.max_exit.items()},
            "picks": self.picks,
            "run_net": {str(k): v for k, v in
                        self.run_net.items()},
            "year_state": {str(k): v for k, v in
                           self.year_state.items()},
            "era": self._era}

    def from_dict(self, d):
        self.max_exit = {k: (float("inf") if v == "inf"
                             else int(v))
                         for k, v in d.get("max_exit",
                                           {}).items()}
        self.picks = d.get("picks", [])
        self.run_net = {int(k): v for k, v in
                        d.get("run_net", {}).items()}
        self.year_state = {int(k): v for k, v in
                           d.get("year_state", {}).items()}
        self._era = d.get("era")

    def _tuple(self, row):
        adj = row["pos_adj"]
        bucket = 0 if adj < BUCKET_E1 else\
            (1 if adj < BUCKET_E2 else 2)
        return (SYM_IDX[row["sym"]], int(row["side"]),
                float(row["dist"]), float(row["score"]),
                float(row["exp"]), float(_margin(row, self._equations)),
                bool(row["in_band"]),
                None if row["net"] is None
                else float(row["net"]),
                None if row["exit"] is None
                else int(row["exit"]),
                int(bucket), float(row["entry_px"]))

    def _record(self, row, ts, tier):
        pick = {"sym": row["sym"], "entry_s": int(ts),
                "side": int(row["side"]),
                "dist": float(row["dist"]),
                "entry_px": float(row["entry_px"]),
                "score": float(row["score"]),
                "tier": int(tier),
                "layer": "persym",
                "exit": row["exit"], "net": row["net"],
                "_counted": row["net"] is not None}
        self.picks.append(pick)
        if row["exit"] is None:
            self.max_exit[row["sym"]] = float("inf")
        else:
            self.max_exit[row["sym"]] = max(
                self.max_exit.get(row["sym"], -1),
                int(row["exit"]))
        if row["net"] is not None:
            w = _weeknum(ts)
            self.run_net[w] = self.run_net.get(w, 0.0)\
                + float(row["net"])
            ys = self.year_state.setdefault(
                _year_of(ts), [0, 0])
            ys[0] += 1
            if row["net"] > 0:
                ys[1] += 1
        return pick

    def resolve_pending(self, m15_bars):
        for pick in self.picks:
            if pick["exit"] is not None:
                continue
            bars = m15_bars.get(pick["sym"])
            if bars is None:
                continue
            xp, net = _trade_outcome(
                bars, pick["sym"], pick["entry_s"],
                pick["side"], pick["dist"])
            if xp is None:
                continue
            pick["exit"] = int(xp)
            pick["net"] = float(net)
            ex = [p["exit"] if p["exit"] is not None
                  else float("inf")
                  for p in self.picks
                  if p["sym"] == pick["sym"]]
            self.max_exit[pick["sym"]] = max(ex)
            if not pick.get("_counted", False):
                pick["_counted"] = True
                w = _weeknum(pick["entry_s"])
                self.run_net[w] = self.run_net.get(w, 0.0)\
                    + float(net)
                ys = self.year_state.setdefault(
                    _year_of(pick["entry_s"]), [0, 0])
                ys[0] += 1
                if net > 0:
                    ys[1] += 1

    def process_slot(self, ts, era, rows):
        """The composed fill at one slot: both the WDIV
        pick and the hook-off (plain) pick are computed
        from the same pre-slot state; where they differ
        and the slot's year is protected (running win
        rate at/below T_PROT with >= 1 committed pick),
        the re-deal is refused (hook-off committed) iff
        it would leave the year's running win rate lower
        than the hook-off pick would."""
        if era != self._era:
            self._era = era
            self.run_net = {}
            self.year_state = {}
        e = self.ev[era]
        e["slots_total"] += 1
        if not rows:
            e["unfilled_no_rows"] += 1
            return []
        taus = {SYM_IDX[s]: float(self._equations[s]["tau"])
                for s in SYMBOLS}
        max_exit_i = {SYM_IDX[k]: v for k, v in
                      self.max_exit.items()}
        tups = [self._tuple(r) for r in rows]
        losing = {w for w, v in self.run_net.items()
                  if v < 0}
        p_w, tier_w = _sel_wdiv(tups, max_exit_i, ts, taus,
                                self._lose_weeks, losing)
        p_o, tier_o = _sel_plain(tups, max_exit_i, ts, taus)
        if p_w is None:
            e["unfilled_all_blocked"] += 1
            return []
        chosen, tier = p_w, tier_w
        if (p_o is not None
                and (p_w[0], p_w[1]) != (p_o[0], p_o[1])):
            y = _year_of(ts)
            py, wy = self.year_state.get(y, [0, 0])
            if py >= 1 and (wy / py) <= T_PROT + 1e-12:
                r_w = (wy + (1 if (p_w[7] or 0) > 0
                             else 0)) / (py + 1)
                r_o = (wy + (1 if (p_o[7] or 0) > 0
                             else 0)) / (py + 1)
                if r_w < r_o - 1e-12:
                    chosen, tier = p_o, tier_o
        idx = tups.index(chosen)
        if tier == 2:
            e["tier2"] += 1
        elif tier == 3:
            e["tier3"] += 1
        e["picks"] += 1
        self._record(rows[idx], ts, tier)
        return [idx]


def _state_path():
    from core.new8_candidate import default_state_path
    return default_state_path(SYSTEM_NAME)


def _bars_from_frame(df):
    """App frame (DataFrame with a time column and
    OHLC) -> (ts, o, h, l, c) numpy arrays sorted by
    time."""
    if df is None or not len(df):
        return None
    try:
        tcol = next(c for c in df.columns
                    if c.lower() in ("datetime", "time",
                                     "timestamp"))
        ts = (pd.to_datetime(df[tcol], utc=True)
              .astype("int64") // 10 ** 9).to_numpy(np.int64)
        o = df["Open"].to_numpy(np.float64)
        h = df["High"].to_numpy(np.float64)
        l = df["Low"].to_numpy(np.float64)
        c = df["Close"].to_numpy(np.float64)
    except Exception:
        return None
    order = np.argsort(ts, kind="stable")
    return (ts[order], o[order], h[order], l[order],
            c[order])


class _Form:
    """Live form of the MSTACK design. Both parents
    settle in parallel on their own FillStates inside
    the persisted MayStackState; each slot's composed
    take is decided causally by the same stack rule as
    the research drives — the filed PREF take, then
    the BMR / DENS / RW-ADD layer reading only the
    committed recorded picks — and every recorded
    stack pick at the slot (main, replacement or add)
    is delivered. State updates read the committed
    picks' recorded nets (resolved in the delivered
    frames, as in the research drives). Persisted:
    the stack state (both parents, composed ledger,
    layer state), the delivered ledger and the
    processed checks."""

    def __init__(self, path=None):
        self.path = path or _state_path()
        self.stack = MayStackState()
        self.delivered = []
        self.processed = []
        self._load()

    def _load(self):
        import json
        if not self.path or not os.path.exists(self.path):
            return
        try:
            with open(self.path) as fh:
                d = json.load(fh)
        except Exception:
            return
        self.processed = d.get("processed", [])
        if "stack" in d:
            self.stack.from_dict(d["stack"])
        out = []
        for r in d.get("delivered", []):
            r = dict(r)
            for k in ("check", "entry_time", "exit_time",
                      "entry_candle"):
                if r.get(k) is not None:
                    r[k] = pd.Timestamp(r[k])
            out.append(r)
        self.delivered = out

    def save(self):
        import json
        if not self.path:
            return
        os.makedirs(os.path.dirname(
            os.path.abspath(self.path)), exist_ok=True)

        def ser(rows):
            out = []
            for r in rows:
                dd = dict(r)
                for k in ("check", "entry_time",
                          "exit_time", "entry_candle"):
                    if dd.get(k) is not None:
                        dd[k] = pd.Timestamp(
                            dd[k]).isoformat()
                out.append(dd)
            return out

        with open(self.path, "w") as fh:
            json.dump({"system": SYSTEM_NAME,
                       "stack": self.stack.to_dict(),
                       "delivered": ser(self.delivered),
                       "processed": self.processed}, fh)

    def step(self, frames, check_time_utc, m15_frames,
             open_symbols=(), m5_frames=None):
        chk = pd.Timestamp(check_time_utc)
        if str(chk) in self.processed:
            return [r for r in self.delivered
                    if pd.Timestamp(r["check"]) == chk]
        T = int(chk.timestamp())
        T -= T % 3600  # entries fire at H:00 UTC
        if m15_frames is None:
            m15_frames = fetch_cycle88r_m15_frames()
        m15_bars = {}
        for sym in SYMBOLS:
            b = _bars_from_frame(
                m15_frames.get(sym) if m15_frames else None)
            if b is not None:
                m15_bars[sym] = b
        era = "disc" if _dt.datetime.utcfromtimestamp(
            T).year <= 2023 else "audit"
        self.stack.resolve_pending(m15_bars)
        n0 = len(self.stack.picks)
        self.stack.process_slot(T, era, m15_bars)
        out = []
        for pick in self.stack.picks[n0:]:
            entry_candle = pd.Timestamp(
                _dt.datetime.utcfromtimestamp(T))
            dd = {"check": chk, "symbol": pick["sym"],
                  "direction": "BUY" if pick["side"] > 0
                  else "SELL",
                  "entry_candle": entry_candle,
                  "entry_time": entry_candle,
                  "entry_px": float(pick["entry_px"]),
                  "tp_pips": float(pick["dist"]) * 2.0,
                  "sl_pips": float(pick["dist"]),
                  "exit_time": entry_candle
                  + pd.Timedelta(hours=MAX_HOLD),
                  "dist": float(pick["dist"]),
                  "layer": pick.get("layer", "persym"),
                  "source": pick.get("source"),
                  "system": SYSTEM_NAME}
            self.delivered.append(dd)
            out.append(dd)
        self.processed.append(str(chk))
        self.save()
        return out




