PREF_PW = {'AUDCAD': 95.0, 'AUDCHF': 108.30000000000025, 'AUDJPY': 272.5, 'AUDNZD': 32.5, 'AUDUSD': -80.0, 'CADCHF': -127.5, 'CADJPY': 50.0, 'CHFJPY': 105.0, 'EURAUD': -10.0, 'EURCHF': 0.0, 'EURGBP': -22.5, 'EURJPY': 22.5, 'EURNZD': -10.0, 'GBPAUD': 137.5, 'GBPCAD': 762.5, 'GBPCHF': 227.5, 'GBPJPY': -22.5, 'GBPNZD': 320.0, 'GBPUSD': 82.5, 'NZDCAD': 280.6999999999991, 'NZDCHF': -5.0, 'USDCAD': 100.0, 'USDCHF': -145.0, 'USDJPY': 47.5}
PREF_GAPD = {'AUDCAD': 72.5, 'AUDCHF': 103.30000000000025, 'AUDJPY': 297.5, 'AUDNZD': 60.0, 'AUDUSD': 50.0, 'CADCHF': -227.5, 'CADJPY': 107.5, 'CHFJPY': 52.5, 'EURAUD': 90.0, 'EURCHF': 17.5, 'EURGBP': 12.5, 'EURJPY': 0.0, 'EURNZD': 27.5, 'GBPAUD': 322.5, 'GBPCAD': 652.5, 'GBPCHF': 190.0, 'GBPJPY': -32.5, 'GBPNZD': 590.0, 'GBPUSD': 17.5, 'NZDCAD': 178.30000000000018, 'NZDCHF': -10.0, 'USDCAD': 105.0, 'USDCHF': -144.20000000000059, 'USDJPY': 82.5}


def preference_tables(picks_pw, picks_gp):
    """Per-symbol net sums of two settled books,
    keyed by symbol name."""
    a, b = {}, {}
    for p in picks_pw:
        a[p["sym"]] = a.get(p["sym"], 0.0) + float(p["net"])
    for p in picks_gp:
        b[p["sym"]] = b.get(p["sym"], 0.0) + float(p["net"])
    return a, b


def arbitrate(picks_pw, picks_gp):
    """December R4-033 form over two settled books.
    Returns (picks, sources): the chosen pick dicts
    (copies, tagged with 'source'), in slot order."""
    da = {int(p["entry_s"]): p for p in picks_pw}
    db = {int(p["entry_s"]): p for p in picks_gp}
    out, src = [], {"identical": 0, "pwint": 0, "gapd": 0}
    for s in sorted(set(da) | set(db)):
        pa, pb = da.get(s), db.get(s)
        assert pa is not None and pb is not None, s
        ka = (pa["sym"], int(pa["side"]), float(pa["net"]))
        kb = (pb["sym"], int(pb["side"]), float(pb["net"]))
        if ka == kb:
            q = dict(pa)
            q["source"] = "identical"
            src["identical"] += 1
        elif PREF_GAPD.get(pb["sym"], 0.0)\
                > PREF_PW.get(pa["sym"], 0.0):
            q = dict(pb)
            q["source"] = "gapd"
            src["gapd"] += 1
        else:
            q = dict(pa)
            q["source"] = "pwint"
            src["pwint"] += 1
        out.append(q)
    return out, src


class ArbState:
    """Runs both parents in parallel, each on its
    own FillState and its own tables; the era's
    arbitration runs over the two completed books
    via arbitrate()."""

    def __init__(self):
        self.pw = FillState(EQUATIONS_PW, LOSE_WEEKS_PW)
        self.gp = FillState(EQUATIONS_GAPD,
                            LOSE_WEEKS_GAPD)

    def process_slot(self, T, era, m15_bars):
        self.pw.process_slot(
            T, era, _slot_rows(T, m15_bars, EQUATIONS_PW))
        self.gp.process_slot(
            T, era, _slot_rows(T, m15_bars,
                               EQUATIONS_GAPD))


