def _iso_week29(ts):
    return _dt.datetime.utcfromtimestamp(
        int(ts)).isocalendar()[:2]


def _is_sl_hit29(pick):
    return abs(float(pick["net"]) - (
        -(float(pick["dist"]) + 2.5))) < 0.01


def _filed_take29(pa, pb):
    """The shipped R492 rule for one slot (arbitrate()'s
    per-slot form verbatim): identical takes are the
    shared pick; otherwise GAPD's row iff PREF_GAPD on
    its symbol exceeds PREF_PW on PW's symbol; ties to
    PW-INT. A single-parent slot takes that parent's
    pick, the R005 _Form precedent."""
    if pa is not None and pb is not None:
        ka = (pa["sym"], int(pa["side"]), float(pa["net"]))
        kb = (pb["sym"], int(pb["side"]), float(pb["net"]))
        if ka == kb:
            return pa, "identical", "pw"
        if PREF_GAPD.get(pb["sym"], 0.0)\
                > PREF_PW.get(pa["sym"], 0.0):
            return pb, "gapd", "gp"
        return pa, "pwint", "pw"
    if pa is not None:
        return pa, "pwint", "pw"
    return pb, "gapd", "gp"


class MayStackState:
    """The RR12 R029 MSTACK-N book: the CTRL12N composed
    book (both 88q parents on their own FillStates at
    the NEW-LAW walk, the filed PREF arbitrate() rule)
    settled by the inner ArbState, composed with a
    recorded-pick layer. At each slot the filed rule
    records at most ONE main pick, priced under its
    source parent b* (gp iff the take is GAPD's, else
    pw); every composed-layer row at the slot is priced
    under b*: (a) BMR -- when the recorded main pick is
    a loss AND either its SL distance >= BMR_DIST_MIN
    (BRA arm) or it extends this composed MAIN stream's
    consecutive-loss run to >= 2 (BLK arm, any
    distance), the recorded pick is replaced by the
    best same-slot alternative row (b*-priced, in-band,
    net > 0, strictly smaller distance, different
    symbol, not recorded at the slot, unblocked in this
    composed book's recorded-pick ledger); (b) DENS --
    a BRA-qualifying loss at distance >= DENS_DIST_MIN
    with NO alternative row is dropped (not recorded);
    (c) DENS-PAIR -- a main pick that would be recorded
    as an SL-hit loss with dist in [PAIR_DIST_LO,
    PAIR_DIST_HI) is dropped when a loss of the same
    class already sits among the last 10 recorded
    picks; (c2) BRD (R039) -- a recorded main loss
    with dist in [CONV_DIST_LO, CONV_DIST_HI) that
    BMR did not convert (and DENS did not drop) gets
    the same replacement search BEFORE the ceiling
    reads it (conversion priority; a slot BMR
    already searched is not re-searched -- the
    result is identical and is counted brd_no_alt);
    found -> recorded as a BRD replacement, not
    found -> the BRD-WIDE fallback (R045) runs the
    same search over the slot's OTHER-parent row
    set without the in-band gate (net > 0, strictly
    smaller distance, different symbol, unblocked;
    ranked by the host key); found -> recorded as
    a BRW replacement, not found -> recorded as-is
    (no drop) (replacements keep priority: the ceiling
    reads only picks that would otherwise be recorded;
    a dropped pick updates neither the loss-run counter
    nor the week ledger); (d) RW-ADD -- after the
    slot's main pick is recorded, if this book's
    running net in the slot's ISO week is < 0, one
    second pick is added at the same slot (best row
    priced under b*, net > 0, unblocked, not already
    recorded at the slot). The replacement trigger and
    loss-run state read the composed MAIN stream only
    and are decided per pick in slot order before the
    slot's add, so the adds layer cannot clear the
    trigger. Only recorded picks change; the inner
    parents settle their own ledgers first. Drive
    convention (R005 form): a FRESH MayStackState
    per era."""

    def __init__(self):
        self.arb = ArbState()
        self.picks = []
        self.host_picks = []
        self.rec_exit = {}
        self.run_net = {}
        self.main_run = 0
        self.census = {"slots": 0, "mains": 0,
                       "one_parent": 0, "bmr_bra": 0,
                       "bmr_blk": 0, "bmr_replace": 0,
                       "bmr_no_alt": 0, "dens_drop": 0,
                       "pair_drop": 0, "brd_replace": 0,
                       "brd_no_alt": 0, "brw_replace": 0,
                       "adds": 0}
        self.surg = []

    # -- persistence (candidate _Form + drive) --
    def to_dict(self):
        return {"arb_pw": self.arb.pw.to_dict(),
                "arb_gp": self.arb.gp.to_dict(),
                "picks": self.picks,
                "host_picks": self.host_picks,
                "rec_exit": {k: ("inf" if v == float("inf")
                                 else int(v))
                             for k, v in
                             self.rec_exit.items()},
                "run_net": {f"{k[0]}-{k[1]}": v
                            for k, v in
                            self.run_net.items()},
                "main_run": self.main_run,
                "census": self.census}

    def from_dict(self, d):
        if "arb_pw" in d:
            self.arb.pw.from_dict(d["arb_pw"])
        if "arb_gp" in d:
            self.arb.gp.from_dict(d["arb_gp"])
        self.picks = d.get("picks", [])
        self.host_picks = d.get("host_picks", [])
        self.rec_exit = {k: (float("inf") if v == "inf"
                             else int(v))
                         for k, v in d.get("rec_exit",
                                           {}).items()}
        self.run_net = {}
        for k, v in d.get("run_net", {}).items():
            y, w = k.split("-")
            self.run_net[(int(y), int(w))] = v
        self.main_run = d.get("main_run", 0)
        self.census = d.get("census", self.census)

    def resolve_pending(self, m15_bars):
        self.arb.pw.resolve_pending(m15_bars)
        self.arb.gp.resolve_pending(m15_bars)
        for pick in self.picks:
            if pick["exit"] is not None:
                continue
            bars = m15_bars.get(pick["sym"])
            if bars is None:
                continue
            xp, net = _trade_outcome(
                bars, pick["sym"], pick["entry_s"],
                pick["side"], pick["dist"])
            if xp is None:
                continue
            pick["exit"] = int(xp)
            pick["net"] = float(net)
        self.rec_exit = {}
        for p in self.picks:
            ex = p["exit"] if p["exit"] is not None\
                else float("inf")
            self.rec_exit[p["sym"]] = max(
                self.rec_exit.get(p["sym"], -1), ex)

    # -- composed bookkeeping --
    def _unblocked(self, sym, T):
        return self.rec_exit.get(sym, -1) <= T

    def _best(self, rows, T, dist_max, skip_syms):
        cand = []
        for r in rows:
            if not r["in_band"]:
                continue
            if r["net"] is None or float(r["net"]) <= 0:
                continue
            if not float(r["dist"]) < dist_max:
                continue
            if r["sym"] in skip_syms:
                continue
            if not self._unblocked(r["sym"], T):
                continue
            cand.append(r)
        if not cand:
            return None
        return min(cand, key=lambda r: (
            -float(r["score"]), float(r["dist"]),
            SYM_IDX[r["sym"]],
            0 if r["side"] > 0 else 1))

    def _best_open(self, rows, T, dist_max, skip_syms):
        """The widened pass (R045 BRW): the host's
        _best discipline WITHOUT the in-band gate --
        used ONLY on the other parent's row set at
        BRD no-alt slots (freeze_rule45_amendment
        .txt files the basis)."""
        cand = []
        for r in rows:
            if r["net"] is None or float(r["net"]) <= 0:
                continue
            if not float(r["dist"]) < dist_max:
                continue
            if r["sym"] in skip_syms:
                continue
            if not self._unblocked(r["sym"], T):
                continue
            cand.append(r)
        if not cand:
            return None
        return min(cand, key=lambda r: (
            -float(r["score"]), float(r["dist"]),
            SYM_IDX[r["sym"]],
            0 if r["side"] > 0 else 1))

    def _record(self, row, T, b, source):
        pick = {"sym": row["sym"], "entry_s": int(T),
                "side": int(row["side"]),
                "dist": float(row["dist"]),
                "entry_px": float(row["entry_px"]),
                "score": float(row["score"]),
                "tier": 1 if b == "pw" else 2,
                "layer": "mstack",
                "exit": row["exit"], "net": row["net"],
                "_counted": row["net"] is not None,
                "source": source}
        self.picks.append(pick)
        if row["exit"] is None:
            self.rec_exit[row["sym"]] = float("inf")
        else:
            self.rec_exit[row["sym"]] = max(
                self.rec_exit.get(row["sym"], -1),
                int(row["exit"]))
        wk = _iso_week29(T)
        self.run_net[wk] = self.run_net.get(wk, 0.0)\
            + float(row["net"] or 0.0)
        return pick

    def _record_main(self, pick, asrc):
        rec = dict(pick)
        rec["source"] = asrc
        self.picks.append(rec)
        if rec["exit"] is None:
            self.rec_exit[rec["sym"]] = float("inf")
        else:
            self.rec_exit[rec["sym"]] = max(
                self.rec_exit.get(rec["sym"], -1),
                int(rec["exit"]))
        wk = _iso_week29(rec["entry_s"])
        self.run_net[wk] = self.run_net.get(wk, 0.0)\
            + float(rec["net"] or 0.0)
        return rec

    def _pair_blocked(self, pick):
        if not _is_sl_hit29(pick):
            return False
        if not (PAIR_DIST_LO <= float(pick["dist"])
                < PAIR_DIST_HI):
            return False
        for x in self.picks[-10:]:
            if float(x["net"] or 0.0) <= 0\
                    and _is_sl_hit29(x)\
                    and PAIR_DIST_LO <= float(x["dist"])\
                    < PAIR_DIST_HI:
                return True
        return False

    def process_slot(self, T, era, m15_bars):
        rows_pw = _slot_rows(T, m15_bars, EQUATIONS_PW)
        rows_gp = _slot_rows(T, m15_bars, EQUATIONS_GAPD)
        n0 = (len(self.arb.pw.picks),
              len(self.arb.gp.picks))
        self.arb.pw.process_slot(T, era, rows_pw)
        self.arb.gp.process_slot(T, era, rows_gp)
        new_pw = self.arb.pw.picks[n0[0]:]
        new_gp = self.arb.gp.picks[n0[1]:]
        if not new_pw and not new_gp:
            return []
        self.census["slots"] += 1
        pa = new_pw[0] if new_pw else None
        pb = new_gp[0] if new_gp else None
        if pa is None or pb is None:
            self.census["one_parent"] += 1
        main_pick, asrc, b = _filed_take29(pa, pb)
        host = dict(main_pick)
        host["source"] = asrc
        self.host_picks.append(host)
        self.census["mains"] += 1
        rows = rows_gp if b == "gp" else rows_pw
        rows_other = rows_pw if b == "gp" else rows_gp
        b_other = "pw" if b == "gp" else "gp"
        made = []
        dropped = False
        rec = None
        searched = False
        if main_pick["net"] is not None\
                and float(main_pick["net"]) <= 0:
            d = float(main_pick["dist"])
            bra = d >= BMR_DIST_MIN
            blk = self.main_run >= 1
            if bra or blk:
                if bra:
                    self.census["bmr_bra"] += 1
                if blk:
                    self.census["bmr_blk"] += 1
                searched = True
                alt = self._best(rows, T, d,
                                 {main_pick["sym"]})
                if alt is not None:
                    rec = self._record(alt, T, b, "BMR")
                    self.census["bmr_replace"] += 1
                    self.surg.append({
                        "kind": "replace",
                        "entry_s": int(T),
                        "rec_idx": len(self.picks) - 1,
                        "orig": host})
                else:
                    self.census["bmr_no_alt"] += 1
                    if bra and d >= DENS_DIST_MIN:
                        dropped = True
                        self.census["dens_drop"] += 1
                        self.surg.append({
                            "kind": "dens_drop",
                            "entry_s": int(T),
                            "dropped": host})
        if dropped:
            return made
        if rec is None\
                and float(main_pick["net"] or 0.0) <= 0\
                and CONV_DIST_LO\
                <= float(main_pick["dist"])\
                < CONV_DIST_HI:
            alt2 = None
            if not searched:
                alt2 = self._best(
                    rows, T, float(main_pick["dist"]),
                    {main_pick["sym"]})
            if alt2 is not None:
                rec = self._record(alt2, T, b, "BRD")
                self.census["brd_replace"] += 1
                self.surg.append({
                    "kind": "brd_replace",
                    "entry_s": int(T),
                    "rec_idx": len(self.picks) - 1,
                    "orig": host})
            else:
                alt3 = self._best_open(
                    rows_other, T, float(main_pick["dist"]),
                    {main_pick["sym"]})
                if alt3 is not None:
                    rec = self._record(alt3, T, b_other,
                                       "BRW")
                    self.census["brw_replace"] += 1
                    self.surg.append({
                        "kind": "brw_replace",
                        "entry_s": int(T),
                        "rec_idx": len(self.picks) - 1,
                        "orig": host})
                else:
                    self.census["brd_no_alt"] += 1
        if rec is None:
            if float(main_pick["net"] or 0.0) <= 0\
                    and self._pair_blocked(main_pick):
                self.census["pair_drop"] += 1
                self.surg.append({
                    "kind": "pair_drop",
                    "entry_s": int(T),
                    "dropped": host})
                return made
            rec = self._record_main(main_pick, asrc)
        if float(rec["net"] or 0.0) <= 0:
            self.main_run += 1
        else:
            self.main_run = 0
        made.append(rec)
        wk = _iso_week29(T)
        if self.run_net.get(wk, 0.0) < 0:
            add = self._best(rows, T, float("inf"),
                             {p["sym"] for p in made})
            if add is not None:
                rec2 = self._record(add, T, b, "RWADD")
                self.census["adds"] += 1
                self.surg.append({
                    "kind": "add", "entry_s": int(T),
                    "rec_idx": len(self.picks) - 1})
                made.append(rec2)
        return made
